#include <bits/stdc++.h>
using namespace std;
int idx(int i,int j,int n){return i*(2*n-i-1)/2+j-i-1;}
uint64_t permute(uint64_t m,const vector<int>&p,int n){uint64_t r=0;for(int i=0;i<n;i++)for(int j=i+1;j<n;j++){int a=p[i],b=p[j];bool w=(a<b)?((m>>idx(a,b,n))&1):!((m>>idx(b,a,n))&1);r|=(uint64_t)w<<idx(i,j,n);}return r;}
vector<vector<int>> perms(int n){vector<vector<int>> v;vector<int>p(n);iota(p.begin(),p.end(),0);do{v.push_back(p);}while(next_permutation(p.begin(),p.end()));return v;}
vector<int> cr_color(vector<uint64_t>&tt,int n,int &nc){int N=tt.size();vector<int>c(N*n,0),z(N*n,0);for(int it=0;it<n+1;it++){map<tuple<int,vector<int>,vector<int>>,int>pal;for(int k=0;k<N;k++)for(int i=0;i<n;i++){vector<int>up,down;for(int j=0;j<n;j++)if(j!=i){int v=(i<j)?((tt[k]>>idx(i,j,n))&1):!((tt[k]>>idx(j,i,n))&1);(v?up:down).push_back(c[k*n+j]);}sort(up.begin(),up.end());sort(down.begin(),down.end());auto key=make_tuple(c[k*n+i],up,down);auto it=pal.find(key);if(it==pal.end()){int id=pal.size()+1;pal.emplace(key,id);z[k*n+i]=id;}else z[k*n+i]=it->second;}
 bool stable=(it>0 && (int)pal.size()==*max_element(c.begin(),c.end()));c.swap(z);if(stable)break;}
 map<vector<int>,vector<int>> cls;for(int k=0;k<N;k++){vector<int> s;for(int i=0;i<n;i++)s.push_back(c[k*n+i]);sort(s.begin(),s.end());cls[s].push_back(k);}
 nc=cls.size();int b=0;for(auto&[k,v]:cls)if(v.size()>1){cout<<"  COLLISION size="<<v.size()<<" reps=";for(int i:v)cout<<tt[i]<<",";cout<<"\n";b++;}return c;}
int main(){vector<uint64_t> rep{0};for(int n=2;n<=6;n++){auto pp=perms(n);set<uint64_t>st;for(auto r:rep)for(int x=0;x<(1<<(n-1));x++){uint64_t t=0;for(int i=0;i<n-1;i++)for(int j=i+1;j<n-1;j++)t|=((r>>idx(i,j,n-1))&1ULL)<<idx(i,j,n);for(int i=0;i<n-1;i++)t|=(uint64_t)((x>>i)&1)<<idx(i,n-1,n);uint64_t best=UINT64_MAX;for(auto&p:pp){uint64_t y=permute(t,p,n);if(y<best)best=y;}st.insert(best);}rep.assign(st.begin(),st.end());cout<<"n="<<n<<" types="<<rep.size()<<flush;int nc;auto colors=cr_color(rep,n,nc);cout<<" C2 classes="<<nc<<"\n";static const int expected_types[]={0,0,1,2,4,12,56};static const int expected_classes[]={0,0,1,2,4,12,55};if((int)rep.size()!=expected_types[n]||nc!=expected_classes[n])return 1;}cout<<"VERIFY_OK 56_TYPES 55_C2_CLASSES\n";return 0;}
